<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Notifications\DatabaseNotification;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;
class ProcessHrNotifications extends Command{protected$signature='hr:process-notifications {--commit}';protected$description='Preview or process queued HR notifications without calling external providers';public function handle():int{if(!config('hr.features.engagement_analytics',false)||!config('hr.system_user_id')||!Schema::hasTable('hr_notification_outbox'))return self::SUCCESS;$commit=(bool)$this->option('commit');$count=0;DB::table('hr_notification_outbox')->where('status','queued')->where('available_at','<=',now())->chunkById(100,function($rows)use($commit,&$count){foreach($rows as$o){$count++;if(!$commit)continue;$payload=decrypt($o->encrypted_rendered_payload);abort_unless(hash_equals($o->payload_checksum,hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))),409,'Queued HR notification integrity check failed.');if($o->channel==='in_app'){$notificationId=hash('sha256',$o->id);DatabaseNotification::firstOrCreate(['id'=>substr($notificationId,0,8).'-'.substr($notificationId,8,4).'-4'.substr($notificationId,13,3).'-a'.substr($notificationId,17,3).'-'.substr($notificationId,20,12)],['type'=>'App\\Notifications\\HrGovernedNotification','notifiable_type'=>'App\\Models\\User','notifiable_id'=>$o->recipient_user_id,'data'=>['notification_type'=>$o->event_type,'title'=>$payload['subject']?:'HR notification','message'=>$payload['body'],'source_type'=>$o->source_type,'source_id'=>$o->source_id]]);$attempt=$o->attempt_count+1;DB::table('hr_notification_outbox')->where('id',$o->id)->update(['status'=>'delivered','attempt_count'=>$attempt,'delivered_at'=>now(),'external_reference'=>$notificationId,'updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insertOrIgnore(['id'=>(string)Str::uuid(),'outbox_id'=>$o->id,'event_type'=>'delivered','attempt_number'=>$attempt,'payload_checksum'=>$o->payload_checksum,'external_reference'=>$notificationId,'actor_user_id'=>config('hr.system_user_id'),'occurred_at'=>now()]);}else{DB::table('hr_notification_outbox')->where('id',$o->id)->update(['status'=>'pending_delivery','updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insertOrIgnore(['id'=>(string)Str::uuid(),'outbox_id'=>$o->id,'event_type'=>'handed_off','attempt_number'=>0,'payload_checksum'=>$o->payload_checksum,'actor_user_id'=>config('hr.system_user_id'),'occurred_at'=>now()]);}}});$this->info(($commit?'Processed ':'Would process ').$count.' HR notification(s).');return self::SUCCESS;}}
